package com.madlava;
import static org.junit.jupiter.api.Assertions.*; import java.nio.charset.StandardCharsets; import java.nio.file.*; import java.time.Duration; import java.util.List; import org.junit.jupiter.api.Test;
class PackagedAgentIT { @Test void packagedAgentProducesFinalSchemaV3Report() throws Exception {String rev=System.getProperty("revision","0.1.0-alpha.2");Path agent=Path.of("target","madlava-agent-"+rev+".jar").toAbsolutePath();Path example=Path.of("target","madlava-agent-"+rev+"-example.jar").toAbsolutePath();Path out=Path.of("target","packaged-agent-it").toAbsolutePath();Files.createDirectories(out);Files.deleteIfExists(out.resolve("madlava.jsonl"));String java=Path.of(System.getProperty("java.home"),"bin","java").toString();Process p=new ProcessBuilder(List.of(java,"-javaagent:"+agent+"=output="+out+",instrumentationInclude=example.app,runtimeObservation=true","-jar",example.toString())).redirectErrorStream(true).start();assertTimeoutPreemptively(Duration.ofSeconds(20),()->assertEquals(0,p.waitFor(),new String(p.getInputStream().readAllBytes(),StandardCharsets.UTF_8)));String report=Files.readString(out.resolve("madlava.jsonl"));assertTrue(report.contains("\"schemaVersion\":3"));assertTrue(report.contains("\"final\":true"));assertTrue(report.contains("\"instanceCounting\""));assertTrue(report.contains("\"throwables\""));assertTrue(report.contains("\"explicitThrows\""));assertTrue(report.contains("\"streamIo\""));assertTrue(report.contains("\"serialization\""));assertTrue(report.contains("\"threadPools\""));assertTrue(report.contains("ExampleApplication$ObservedException"));assertFalse(report.contains("MADLAVA_PACKAGED_SECRET_91827"));assertFalse(report.contains("Exception in thread"));}}
